#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// SevenSegmentDisplay's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/seven_segment_display.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The reading the cells show, right-aligned: digits, the hexadecimal letters, the letters a seven-segment cell can form, '-', '_', '=', the degree sign and spaces; '.' and ',' light the previous cell's point and ':' is a colon cell. Other characters show as blank cells. Must be valid UTF-8 (std::invalid_argument).
template <typename Declaring>
struct SevenSegmentDisplayTextCapability {
    PropertyCell<std::string, SevenSegmentDisplayTextCapability<Declaring>> text{};

    static void assign(SevenSegmentDisplayTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.text), incoming);
        if (!capability.text.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.text));
    }
};

// The digit cells shown, at most 64 (std::invalid_argument); zero shows as many as the text needs. A longer reading keeps its last digits (overflowed()).
template <typename Declaring>
struct SevenSegmentDisplayDigitCountCapability {
    PropertyCell<std::uint32_t, SevenSegmentDisplayDigitCountCapability<Declaring>> digit_count{0U};

    static void assign(SevenSegmentDisplayDigitCountCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.digit_count), incoming);
        if (!capability.digit_count.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.digit_count));
    }
};

// Whether the unlit segments are drawn faintly, as on a real display.
template <typename Declaring>
struct SevenSegmentDisplayGhostSegmentsCapability {
    PropertyCell<bool, SevenSegmentDisplayGhostSegmentsCapability<Declaring>> ghost_segments{true};

    static void assign(SevenSegmentDisplayGhostSegmentsCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.ghost_segments), incoming);
        if (!capability.ghost_segments.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.ghost_segments));
    }
};

// Every SevenSegmentDisplay capability, in the order the declaring class takes them.
template <typename Declaring>
struct SevenSegmentDisplayCapabilities : public SevenSegmentDisplayTextCapability<Declaring>,
                                         public SevenSegmentDisplayDigitCountCapability<Declaring>,
                                         public SevenSegmentDisplayGhostSegmentsCapability<Declaring> {};

} // namespace gui_forms
